    except ValueError:
        return None

import json
def parse_checked(lines):
    rows = []
    bad = 0
    for line in lines:
        if line.strip():
            try:
                rows.append(json.loads(line))
            except json.JSONDecodeError:
                bad += 1
    return rows, bad

